require_once '/var/www/html/wp-load.php';$ids=get_posts(['post_type'=>'product','post_status'=>['publish','draft','pending','private'],'posts_per_page'=>-1,'fields'=>'ids']);$c=['total'=>0,'verified'=>0,'missing'=>0,'not_png'=>0,'under_4k'=>0,'no_alpha_channel'=>0,'no_transparency_chunk'=>0];$bad=[];
